      "card_ids": ["C14"],
      "claim": "Berberine, a structurally related alkaloid, rapidly penetrated the BBB in rats with brain concentrations peaking at 2–4 h after administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "GYKI-52466, a methylenedioxy-containing compound, showed only about 4% steady-state brain-to-plasma ratio, indicating low permeability; its lower structural similarity limits transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a protopine-type alkaloid with two methylenedioxy groups and a tertiary N-methylamine. The closest analogue, allocryptopine, was directly detected in rat CSF, and multiple related methylenedioxy isoquinoline/protoberberine alkaloids show brain penetration in vivo. The single low-permeability example is structurally distant and outweighed by the consistent positive CNS-access evidence.",
  "evidence_gaps": [
    "No direct experimental measurement of protopine itself is available; prediction relies on close analogues.",
    "Quantitative brain-to-plasma or unbound brain concentration for protopine is not reported.",
    "Potential efflux-transporter liability for protopine was not directly assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

